import { randomUUID } from "node:crypto";
import { expect, type Page, test } from "@playwright/test";
import { enrollConsoleOwner } from "./owner-fixture.js";

test.use({ timezoneId: "Europe/Paris" });

test.beforeEach(async ({ page, baseURL }, testInfo) => {
  await enrollConsoleOwner(page, baseURL, testInfo.project.metadata);
});

async function registerProject(page: Page, prefix: string) {
  const name = `${prefix} ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  return { name, url: page.url() };
}

async function openDatabases(page: Page) {
  await page.goto("/databases");
  await expect(page).toHaveURL(/\/databases$/);
  await expect(page.getByRole("heading", { name: "Bases de données", exact: true })).toBeVisible();
}

async function createPreview(page: Page) {
  const name = `review-${randomUUID().slice(0, 8)}`;
  const form = page.getByRole("form", { name: "Créer un aperçu persistant", exact: true });
  await form.getByLabel("Nom de l’aperçu", { exact: true }).fill(name);
  const expiry = form.getByLabel("Expiration de l’aperçu", { exact: true });
  await expect(expiry).toHaveAttribute("required", "");
  await expiry.fill(new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().slice(0, 16));
  await form.getByRole("button", { name: "Créer l’aperçu", exact: true }).click();
  await expect(page.getByRole("heading", { name: `Aperçu : ${name}`, exact: true })).toBeVisible();
  return name;
}

// Keep creation, revision-safe edits and reload together to verify the persisted lifecycle.
test("T-AC-27 T-AC-33 persists project metadata and finite preview limits without claiming provisioning", async ({
  page,
}) => {
  const project = await registerProject(page, "Lifecycle e2e");
  const renamed = `${project.name} modifié`;
  const description = "Projet local destiné à vérifier les métadonnées persistées.";
  const metadata = page.getByRole("form", { name: "Modifier le projet", exact: true });
  const updatedExpiry = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString().slice(0, 16);

  await metadata.getByLabel("Nom du projet", { exact: true }).fill(renamed);
  await metadata
    .getByRole("textbox", { name: "Description du projet", exact: true })
    .fill(description);
  await metadata.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name: renamed, exact: true })).toBeVisible();
  const previewName = await createPreview(page);
  const preview = page.getByRole("region", { name: `Environnement ${previewName}`, exact: true });
  await preview.getByText("Modifier les limites et le nom", { exact: true }).click();
  await preview.getByLabel("Nom de l’environnement", { exact: true }).fill(`${previewName}-v2`);
  await preview.getByLabel("Mémoire (MiB)", { exact: true }).fill("1024");
  await preview.getByLabel("CPU (millicœurs)", { exact: true }).fill("500");
  await preview.getByLabel("Stockage (GiB)", { exact: true }).fill("12");
  await preview.getByLabel("Expiration de l’environnement", { exact: true }).fill(updatedExpiry);
  await preview.getByRole("button", { name: "Enregistrer l’environnement", exact: true }).click();

  await expect(
    page.getByRole("heading", { name: `Aperçu : ${previewName}-v2`, exact: true }),
  ).toBeVisible();
  await page.reload();
  await expect(page.getByRole("heading", { name: renamed, exact: true })).toBeVisible();
  await expect(
    metadata.getByRole("textbox", { name: "Description du projet", exact: true }),
  ).toHaveValue(description);
  const saved = page.getByRole("region", { name: `Environnement ${previewName}-v2`, exact: true });
  await expect(saved.getByText("Prévu", { exact: true })).toBeVisible();
  await expect(saved.getByText("12 Go", { exact: true })).toBeVisible();
  await expect(saved.getByText(/Aucun service déployé/)).toBeVisible();
  await expect(saved.getByText(/^Expiration : /)).toBeVisible();
  await saved.getByText("Modifier les limites et le nom", { exact: true }).click();
  await expect(saved.getByLabel("Mémoire (MiB)", { exact: true })).toHaveValue("1024");
  await expect(saved.getByLabel("CPU (millicœurs)", { exact: true })).toHaveValue("500");
  await expect(saved.getByLabel("Expiration de l’environnement", { exact: true })).toHaveValue(
    updatedExpiry,
  );
  await expect(page.getByRole("heading", { name: "Production", exact: true })).toBeVisible();
  await expect(page.getByRole("heading", { name: "Développement", exact: true })).toBeVisible();
});

// This journey crosses project selection, actual HTTP preparation and reload to detect stale scope.
test("T-AC-28 T-AC-33 prepares a bounded profile for the selected preview and keeps execution blocked", async ({
  page,
}) => {
  const project = await registerProject(page, "Database scoped e2e");
  const previewName = await createPreview(page);
  const foreign = await registerProject(page, "Database foreign e2e");
  await openDatabases(page);
  const form = page.getByRole("form", { name: "Préparer une base indépendante", exact: true });
  const projects = form.getByRole("combobox", { name: "Projet", exact: true });
  const environments = form.getByRole("combobox", { name: "Environnement", exact: true });
  await projects.selectOption({ label: project.name });
  await environments.selectOption({ label: `Aperçu : ${previewName}` });
  await projects.selectOption({ label: foreign.name });
  await expect(environments.locator("option")).toHaveCount(2);
  await expect(
    environments.getByRole("option", { name: "Production", exact: true }),
  ).toBeAttached();
  await expect(
    environments.getByRole("option", { name: "Développement", exact: true }),
  ).toBeAttached();
  await projects.selectOption({ label: project.name });
  await environments.selectOption({ label: `Aperçu : ${previewName}` });
  await form.getByLabel("CPU PostgreSQL (millicœurs)", { exact: true }).fill("750");
  await form.getByLabel("Mémoire PostgreSQL (MiB)", { exact: true }).fill("768");
  await form.getByLabel("Données PostgreSQL (GiB)", { exact: true }).fill("3");
  await form.getByLabel("Journaux WAL (GiB)", { exact: true }).fill("2");
  await form.getByLabel("Temporaire PostgreSQL (MiB)", { exact: true }).fill("64");
  await form.getByLabel("Connexions PostgreSQL maximales", { exact: true }).fill("40");

  const prepared = page.waitForResponse(
    (response) =>
      new URL(response.url()).pathname.endsWith("/databases/preparations") &&
      response.request().method() === "POST",
  );
  await form.getByRole("button", { name: "Préparer le profil PostgreSQL", exact: true }).click();
  expect((await prepared).status()).toBe(201);

  const card = page.getByRole("region", {
    name: `Profil ${project.name} ${previewName}`,
    exact: true,
  });
  await expect(card).toBeVisible();
  await expect(card.getByText("3 GiB", { exact: true })).toBeVisible();
  await expect(card.getByText("2 GiB", { exact: true })).toBeVisible();
  await expect(card.getByText("40", { exact: true })).toBeVisible();
  await expect(card.getByText("Prévu", { exact: true })).toBeVisible();
  await expect(card.getByRole("button", { name: "Provisionner", exact: true })).toBeDisabled();
  await expect(
    page.getByRole("region", { name: `Profil ${foreign.name} ${previewName}`, exact: true }),
  ).toHaveCount(0);
  await page.reload();
  await expect(card).toBeVisible();
  await expect(card.getByRole("button", { name: "Provisionner", exact: true })).toBeDisabled();
  await expect(
    page.getByRole("heading", { name: "Exécution indisponible", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Exécution de sauvegarde à qualifier", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByText(/sauvegarde à connecter, restauration à connecter, rotation à connecter/),
  ).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Rotation des secrets à connecter", exact: true }),
  ).toBeVisible();
  const cadence = page.getByRole("region", { name: "Cadence réelle des sauvegardes" });
  await expect(
    cadence.getByText(/Inconnu · source non configurée|Aucune cellule/).first(),
  ).toBeVisible();
  await expect(cadence.getByText(/Dernier test de restauration enregistré/)).toBeVisible();
  await expect(page.getByText(/Aucun canal de notification externe n’est configuré/)).toBeVisible();
  await expect(page.getByRole("heading", { name: "Incidents", exact: true })).toBeVisible();
  await expect(
    page.getByText(/Activation bloquée : fichiers, authentification, configuration/),
  ).toBeVisible();
  await expect(
    page
      .getByRole("form", { name: "Préparer une sauvegarde physique", exact: true })
      .getByRole("button", { name: "Préparer la sauvegarde", exact: true }),
  ).toBeDisabled();
  await expect(
    page
      .getByRole("form", { name: "Préparer une restauration isolée", exact: true })
      .getByRole("button", { name: "Préparer la restauration isolée", exact: true }),
  ).toBeDisabled();
  await expect(page.getByRole("button", { name: "Suspendre la base", exact: true })).toHaveCount(0);
  await page.screenshot({ path: "artifacts/databases-desktop.png", fullPage: true });
});

test("T-AC-33 fits project and database management on mobile without exposing private connection material", async ({
  page,
}) => {
  const project = await registerProject(page, "Mobile database e2e");
  await page.setViewportSize({ width: 390, height: 844 });
  for (const route of [project.url, "/databases"]) {
    await page.goto(route);
    await expect(page.locator("h1")).toBeVisible();
    expect(
      await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth),
    ).toBeLessThanOrEqual(1);
    const revealsPrivateMaterial = await page
      .getByRole("main")
      .evaluate((main) =>
        /postgres(?:ql)?:\/\/|-----BEGIN [A-Z ]*PRIVATE KEY-----|PGPASSWORD=/.test(
          main.textContent ?? "",
        ),
      );
    expect(revealsPrivateMaterial).toBe(false);
  }
  await expect(
    page.getByRole("heading", { name: "Exécution indisponible", exact: true }),
  ).toBeVisible();
  await page.screenshot({ path: "artifacts/databases-mobile.png", fullPage: true });
});
